select 'eat-train-live', 'Eat Train Live', 'Eat Train Live', '1:1 and 2:1 PT at a private facility in St Asaph', 'Eat Train Live delivers tailored one-to-one and two-to-one personal training at its private facility in St Asaph, with weekly check-ins.', 'St Asaph', 'Wales', 'LL17', extensions.st_setsrid(extensions.st_makepoint(-3.4369, 53.2522), 4326)::extensions.geography, true, false, false, null, null, '{}'::text[], null, 'https://www.eattrainlive.co.uk/personaltraining', null, null, null, null, false, '{}'::text[], 'website', 'https://www.eattrainlive.co.uk/personaltraining', 'Business details published on the trainer''s own website', now(), false, 'published'
